   438→    <h1 id="title">{{ title }}</h1>
   439→
   440→    {% if sessions and sessions|length > 1 %}
   441→    <div class='navigation'>
   442→        <h2>Sessions</h2>
   443→        <span style='font-size: 0.75em;'>↓ Click a box below to scroll down to the corresponding
   444→            session</span>
   445→        <div class='session-nav'>
   446→            {% for session in sessions %}
   447→            <a href='#session-{{ session.id }}' class='session-link'>
   448→                <div class='session-link-title'>
   449→                    {% if session.summary %}
   450→                    {{ session.summary }} •
   451→                    {% endif %}
   452→                    {{ session.id[:8] }}
   453→                </div>
   454→                <div class='session-link-meta'>
   455→                    {{ session.timestamp_range }} • {{ session.message_count }} messages
   456→                    {% if session.token_summary %}
   457→                    <br>{{ session.token_summary }}
   458→                    {% endif %}
   459→                </div>
   460→                {% if session.first_user_message %}
   461→                <pre class='session-preview' style='font-size: 0.75em; line-height: 1.3; padding-bottom: 0;'>
   462→                    {{- session.first_user_message[:500]|e -}}{% if session.first_user_message|length > 500 %}...{% endif %}
   463→                </pre>
   464→                {% endif %}
   465→            </a>
   466→            {% endfor %}
   467→        </div>
   468→    </div>
   469→    {% endif %}
   470→
   471→    {% for message in messages %}
   472→    {% if message.is_session_header %}
   473→    <div class="session-divider"></div>
   474→    <div id='session-{{ message.session_id }}' class='message session-header'>
   475→        <div class='header'>Session: {{ message.content_html }}</div>
   476→        {% if message.session_subtitle %}
   477→        <div class='session-subtitle' style='font-size: 0.9em; color: #666; margin-top: 4px;'>{{
   478→            message.session_subtitle }} ({{message.session_subtitle.session_id}})</div>
   479→        {% endif %}
   480→
   481→    </div>
   482→    {% else %}
   483→    <div class='message {{ message.css_class }}'>
   484→        <div class='header'>
   485→            <span>{% if message.css_class == 'user' %}🤷 {% elif message.css_class == 'assistant' %}🤖 {% elif
   486→                message.css_class == 'system' %}⚙️ {% endif %}{{ message.display_type }}</span>
   487→            <div style='display: flex; flex-direction: column; align-items: flex-end; gap: 2px;'>
   488→                <span class='timestamp'>{{ message.formatted_timestamp }}</span>
   489→                {% if message.token_usage %}
   490→                <span class='token-usage' style='font-size: 0.75em; color: #888;'>{{ message.token_usage }}</span>
   491→                {% endif %}
   492→            </div>
   493→        </div>
   494→        <div class='content'>{{ message.content_html | safe }}</div>
   495→    </div>
   496→    {% endif %}
   497→    {% endfor %}
   498→
   499→    <button class="toggle-details" id="toggleDetails" title="Toggle all details">📋</button>
   500→    <a class="scroll-top" title="Scroll to top" href="#title">🔝</a>
   501→
   502→    <script>
   503→        document.addEventListener('DOMContentLoaded', function () {
   504→            const toggleButton = document.getElementById('toggleDetails');
   505→
   506→            function updateToggleButton() {
   507→                const allDetails = document.querySelectorAll('details.collapsible-details');
   508→                const openCount = document.querySelectorAll('details[open].collapsible-details').length;
   509→                const totalCount = allDetails.length;
   510→
   511→                if (totalCount === 0) {
   512→                    toggleButton.style.display = 'none';
   513→                    return;
   514→                }
   515→
   516→                // If more than half are open, show "close all" state, otherwise show "open all"
   517→                const mostlyOpen = openCount > totalCount / 2;
   518→                toggleButton.textContent = mostlyOpen ? '📦' : '🗃️';
   519→                toggleButton.title = mostlyOpen ? 'Close all details' : 'Open all details';
   520→            }
   521→
   522→            function toggleAllDetails() {
   523→                const allDetails = document.querySelectorAll('details.collapsible-details');
   524→                const openCount = document.querySelectorAll('details[open].collapsible-details').length;
   525→                const shouldOpen = openCount <= allDetails.length / 2;
   526→
   527→                allDetails.forEach(details => {
   528→                    if (shouldOpen) {
   529→                        details.setAttribute('open', '');
   530→                    } else {
   531→                        details.removeAttribute('open');
   532→                    }
   533→                });
   534→
   535→                updateToggleButton();
   536→            }
   537→
   538→            toggleButton.addEventListener('click', toggleAllDetails);
   539→
   540→            // Initialize button state
   541→            updateToggleButton();
   542→        });
   543→    </script>
